import { html } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// TextSwap.vue as <conare-text-swap>: two labels in one cell, so nothing around them moves (console2.css .v2-swap):
// when `on` turns true the first leaves up and the second arrives from below, each with a touch of blur (160ms fade,
// 220ms move on the strong ease-out), and a check in the second label draws its stroke. Put the labels in the `a` and
// `b` slots, an icon first in each (`<span slot="b" class="contents"><svg ...></svg>Copied</span>`). Reduced motion
// keeps the cross-fade only. The host is the cell (text-swap.css), so a class on it lands as one on <TextSwap> does.

/**
 * @summary Two labels in one cell that swap with a touch of blur.
 * @slot a - The first label, shown while `on` is false.
 * @slot b - The second label, shown once `on` is true.
 */
export class TextSwap extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { on: { type: Boolean, reflect: true } }

	/** Shows the second label. */
	on = false

	render() {
		return html`<span class="ds-swap-a" aria-hidden=${ifDefined(this.on ? 'true' : undefined)}><slot name="a"></slot></span><span class="ds-swap-b" aria-hidden=${ifDefined(!this.on ? 'true' : undefined)}><slot name="b"></slot></span>`
	}
}

define('text-swap', TextSwap)

/* TextSwap.vue's <style>, with the host as .ds-swap (the cell) and `on` as its data-on="true". The check's stroke is
   drawn on the slotted label: stroke-dasharray and stroke-dashoffset are inherited, so its paths take them from it. */
:host { display: inline-grid; }
.ds-swap-a, .ds-swap-b { display: inline-flex; grid-area: 1 / 1; align-items: center; justify-content: center; gap: var(--ds-space-sm); transition: opacity var(--ds-duration-glide) ease, filter var(--ds-duration-glide) ease, transform var(--ds-duration-settle) var(--ds-easing-out); }
.ds-swap-b { opacity: 0; filter: blur(2px); transform: translateY(5px) scale(0.96); }
:host([on]) .ds-swap-a { opacity: 0; filter: blur(2px); transform: translateY(-5px) scale(0.96); }
:host([on]) .ds-swap-b { opacity: 1; filter: none; transform: none; }
slot[name="b"]::slotted(*) { stroke-dasharray: 24; stroke-dashoffset: 24; transition: stroke-dashoffset var(--ds-duration-micro) ease; }
:host([on]) slot[name="b"]::slotted(*) { stroke-dashoffset: 0; transition: stroke-dashoffset var(--ds-duration-enter) var(--ds-easing-out) 40ms; }
@media (prefers-reduced-motion: reduce) {
  .ds-swap-a, .ds-swap-b { filter: none !important; transform: none !important; transition: opacity var(--ds-duration-micro) ease; }
  slot[name="b"]::slotted(*) { stroke-dashoffset: 0; transition: none; }
}
